 "content": "def transform(grid):
    """Fill in color 4 the columns shared by the upper marker bar and lower marker row."""
    out = [row[:] for row in grid]
    if not grid:
        return out
    width = len(grid[0])
    divider = next((r for r, row in enumerate(grid)
                    if len(row) == width and width and row[0] != 0
                    and all(v == row[0] for v in row)), None)
    if divider is None:
        return out
    top_color = grid[0][0]
    top_cols = {c for c, v in enumerate(grid[0]) if v == top_color and top_color != 0}
    bottom_row = grid[-1]
    bottom_cols = {c for c, v in enumerate(bottom_row) if v == top_color}
    for c in top_cols & bottom_cols:
        for r in range(1, divider):
            out[r][c] = 4
    return out
